    stem: 'Whatlessondoesthefolktalewantustolearn? ◆第一篇 本文讲述了一个非洲的民间故事。很久以前，人们以天为食，不需要劳作，但有人却不珍惜 上天赐予的礼物，故意浪费食物，结果激怒了天，受到了惩罚，最终人们吸取了教训。这个故事告 诉我们不要浪费大自然赐予的礼物。 解析：第二段描述了很久以前，天离地非常近，人们不用种植庄稼，饿的时候只需要把天下 一块来吃。天的味道有时像香蕉，有时像烤土豆，总是非常美味。所以答案A“天是食物的来 源”是正确的选择。选项C说“天给人们提供香蕉和土豆”是不对的。 解析：第五段的前两句，第八段的第一句都讲到天非常愤怒，天空变得阴沉，黑云笼罩大地。 说明天在债怒的时候会变黑，也就是答案B。 解析：第七段讲到一个叫Adami的人瓣下了很多片美味的天却吃不完，他知道不能随便丢 掉这些食物，所以把它们藏在一堆垃圾下面。 解析：回答本题需要参考文章最后两段。倒数第二段中愤怒的天对人类说：“以后你们必须 学习在地上种庄稼，在森林中狩猎。”最后一段说天离开后，人们开始努力劳作，自已种庄稼，烧 煮食物。 解析：文章最后一段最后一句说天离开以后，人们一直记着不要浪费大自然赐予的礼物，也 就是粮食。这也是整个故事的中心思想。 Passage Two Each year over 6o0 million people travel internationally.Hundreds of millions more journey within their home country, doing so for both work and pleasure. As a result, the tourist industryincluding hotels, scenic spots, airlines, travel agencies, and other businesses-is described as “the world\'s number one employer." Worldwide, tourism generates an estimated four trillion dollars annually. Individual tourists may not view themselves as part of a worldwide peace movement, but this is how the UN World Tourism Organization describes the industry. In 2004,Francesco Frangialli, Secretary-general of the organization, told a presidential conference in the Middle East,“Tourism and peace are inseparable. The forces released by tourism are so powerful that they can change apparently irreversible situations and bring about peace where none was considered possible." What are the origins of this influential industry? Is tourism truly a force for good? And can “the forces released by tourism" really bring peace? The seeds of the modern tourist industry in the West were sown especially in the 19th century. As the industrial revolution swelled the ranks of the middle classes in Europe and the United States, a growing number of people found themselves with both the money and the time to travel. In addition, great advances were made in methods of mass transportation. Powerful engines pulled passengers between major cities, and great steamships sped them between continents. To deal with the growing traffic, large hotels sprang up near railway terminals and shipping ports. He was the first to combine transportation, accommodation, and.activities at desired locations into a holiday package tour.“Due to the system founded by Mr. Cook," noted the British statesman Will Jam Gladstone in the 1860\'s, “"whole classes have for the first time found easy access to foreign countries and have acquired some of the familiarity with them which breeds not contempt(视）but kindness."',
