    type: 'vocab_grammar',
    stem: 'Which of the following is the proper title of this passage? Passage Two Work is a family responsibility. Right now you are benefiting from the work of your family. Your parents have worked hard to provide for your physical, spiritual, and emotional well-being. They do expect you to share some of the load. On my son\'s Graduation Day from the Harvard Business School, Dean Kim Clark asked each of the graduating students in the front rows to look behind them at their loved ones. As the graduates turned around, Dean Clark paused and said, "Were it not for the support of your family members, you would not be receiving this honor today. " And so it is for each of you. You have received much. In turn, you are expectedeven requiredto offer similar support and love to your own children and families. This does not mean continually “hanging out." As you grow older, your parents expect you to provide for yourselves and become independent. We all share in the work. Remember it is important to start early in life to teach your children that they should do their part in the work of a family. Those of you who have had the experience of growing up in a home where you were taught to work can bear testimony to its value in your life today. We understand that in some places in the world you may encounter hardships when trying to provide for your families. These trials could include serious illness, the loss of a spouse, the addition of an elderly parent, or providing for your children\'s education. But it is my conviction that realization of the importance of work to your family will help you out.',
